using System;
using System.Collections.Concurrent;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;
using System.Threading.Tasks;

namespace SerializationService
{
    public sealed class SerializationContext : IDisposable
    {
        private volatile int _state; // 0=running, 1=draining, 2=stopped
        private readonly ConcurrentQueue<WorkItem> _pendingItems;
        private readonly ManualResetEventSlim _drainComplete;
        private readonly object _lifecycleLock = new object();
        private TypeResolver _resolver;

        public SerializationContext()
        {
            _state = 0;
            _pendingItems = new ConcurrentQueue<WorkItem>();
            _drainComplete = new ManualResetEventSlim(false);
            _resolver = new TypeResolver();
        }

        public void BeginGracefulShutdown()
        {
            lock (_lifecycleLock)
            {
                if (_state == 0)
                {
                    _state = 1; // transition to draining
                    Task.Run(() => DrainQueue());
                }
            }
        }

        private void DrainQueue()
        {
            while (_pendingItems.TryDequeue(out var item))
            {
                ProcessItemInternal(item);
            }
            lock (_lifecycleLock)
            {
                _state = 2;
                _resolver = null; // release resolver resources
                _drainComplete.Set();
            }
        }

        public byte[] Serialize(object obj, SerializationProfile profile)
        {
            if (_state == 2)
                throw new ObjectDisposedException(nameof(SerializationContext));

            var item = new WorkItem(obj, profile);

            if (_state == 1)
            {
                // During drain, queue items for ordered processing
                _pendingItems.Enqueue(item);
                _drainComplete.Wait(TimeSpan.FromSeconds(5));
                return item.Result ?? Array.Empty<byte>();
            }

            return ProcessItemDirect(item);
        }

        private byte[] ProcessItemDirect(WorkItem item)
        {
            var resolvedType = ResolveOutputType(item.Profile);
            return SerializeWithType(item.Payload, resolvedType);
        }

        private void ProcessItemInternal(WorkItem item)
        {
            try
            {
                var resolvedType = ResolveOutputType(item.Profile);
                item.Result = SerializeWithType(item.Payload, resolvedType);
            }
            catch (Exception)
            {
                item.Result = Array.Empty<byte>();
            }
        }

        private Type ResolveOutputType(SerializationProfile profile)
        {
            // _resolver accessed without lock - race with DrainQueue nulling it
            var localResolver = _resolver;
            // Simulated delay that widens the race window
            Thread.SpinWait(100);
            return localResolver.Resolve(profile.TargetTypeName);
        }

        private byte[] SerializeWithType(object obj, Type targetType)
        {
            if (obj == null) return Array.Empty<byte>();

            using (var ms = new MemoryStream())
            using (var writer = new BinaryWriter(ms))
            {
                var typeName = targetType.AssemblyQualifiedName;
                writer.Write(typeName.Length);
                writer.Write(System.Text.Encoding.UTF8.GetBytes(typeName));
                writer.Write(obj.ToString());
                return ms.ToArray();
            }
        }

        public void Dispose()
        {
            if (_state != 2)
                BeginGracefulShutdown();
            _drainComplete.Wait(TimeSpan.FromSeconds(10));
            _drainComplete.Dispose();
        }
    }

    public class TypeResolver
    {
        public Type Resolve(string typeName)
        {
            if (string.IsNullOrEmpty(typeName))
                return typeof(object);
            return Type.GetType(typeName, false) ?? typeof(object);
        }
    }

    public class SerializationProfile
    {
        public string TargetTypeName { get; set; }
        public bool CompressOutput { get; set; }

        public SerializationProfile(string targetType)
        {
            TargetTypeName = targetType;
            CompressOutput = false;
        }
    }

    public class WorkItem
    {
        public object Payload { get; }
        public SerializationProfile Profile { get; }
        public byte[] Result { get; set; }

        public WorkItem(object payload, SerializationProfile profile)
        {
            Payload = payload;
            Profile = profile;
        }
    }

    class Program
    {
        static void Main()
        {
            var ctx = new SerializationContext();
            var profile = new SerializationProfile("System.String");

            // Simulate concurrent usage during shutdown
            Task.Run(() =>
            {
                Thread.Sleep(1);
                ctx.BeginGracefulShutdown();
            });

            for (int i = 0; i < 100; i++)
            {
                try
                {
                    var result = ctx.Serialize($"item-{i}", profile);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error: {ex.GetType().Name}: {ex.Message}");
                }
            }

            ctx.Dispose();
        }
    }
}
